#include "artifact/reader.h"
#include "artifact/materializer.h"
#include "targets/falcon_h1/falcon_h1_binder.h"
#include "targets/falcon_h1/falcon_h1_package.h"
#include "targets/falcon_h1/falcon_h1_layer.h"
#include "core/device.h"
#include "core/layout.h"
#include "core/paged_kv_cache.h"
#include "targets/qwen3_6/impl/runtime/logical_kv_store.h"
#include "targets/qwen3_6/impl/runtime/state_image_store.h"
#include <ninfer/targets/qwen3_6/state_image.h>
#include <cuda_bf16.h>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <vector>
using namespace ninfer;
int main(int argc,char**argv){try{if(argc<5)throw std::runtime_error("usage ARTIFACT INPUT_BF16 OUTPUT_BF16 LAYER");artifact::Reader r(argv[1]);auto b=targets::falcon_h1::bind(r);DeviceContext dev(0);if(dev.compute_capability()!=70)std::cerr<<"NON_QUALIFICATION_DEVICE cc="<<dev.compute_capability()<<"\n";auto mat=artifact::materialize(r,b.materialization,dev);targets::falcon_h1::GptqExecution gptq;gptq.stage(b,mat);const int layer=std::stoi(argv[4]);std::ifstream in(argv[2],std::ios::binary|std::ios::ate);auto n=in.tellg();if(n<=0||n%(3072*2))throw std::runtime_error("input fixture must be BF16 [T,3072]");std::size_t T=n/(3072*2);std::vector<__nv_bfloat16> host(T*3072);in.seekg(0);in.read(reinterpret_cast<char*>(host.data()),n);DeviceBuffer input_dev(host.size()*2),output_dev(host.size()*2);input_dev.copy_from_host(host.data(),host.size()*2);Tensor x(input_dev.p,DType::BF16,{3072,(int)T}),y(output_dev.p,DType::BF16,{3072,(int)T});LayoutBuilder lb;DeviceKVPagePoolSpec ps{.page_group_count=96,.geometry={.page_tokens=64,.device_plane_order=PagedKVPlaneOrder::PageMajor,.planes={}}};for(int l=0;l<44;++l){ps.geometry.planes.push_back({DType::BF16,128,2});ps.geometry.planes.push_back({DType::FP16,128,2});}auto pl=plan_device_kv_page_pool(lb,ps);auto tables_l=plan_kv_execution_tables(lb,{.logical_page_capacity=96,.table_rows=8});targets::qwen3_6::StateImageSpec ss{.linear={.layers=44,.conv_channels=6656,.conv_width=4,.value_heads=24,.value_head_dim=128,.key_head_dim=256,.slot_count=4,.conv_dtype=DType::BF16},.hidden=3072,.falcon=targets::qwen3_6::FalconStatePayloadSpec{44,4}};auto sl=targets::qwen3_6::plan_state_image_device_pool(lb,ss);DeviceArena backing(lb.finish(256));DeviceSpan span{backing.base(),backing.capacity()};DeviceKVPagePool physical(span,pl);KVExecutionTablePool tables(span,tables_l,physical);targets::qwen3_6::detail::LogicalKVPageStore pages(physical,96);targets::qwen3_6::detail::KVAddressSpaceStore kv(pages,tables,8,96);targets::qwen3_6::StateImageDevicePool state(span,sl);targets::qwen3_6::detail::StateImageStore states(state,nullptr,8);auto program=targets::falcon_h1::Package::make_program(b,8192,8,8,4,kv,states,state);auto id=program.create_sequence(0);DeviceArena ws(program.hybrid_workspace_bytes(T));const std::string outdir=std::string(argv[3])+".taps";if(argc>5)targets::falcon_h1::capture_layer_reference_taps(program,id,layer,b,mat,gptq,x,y,{ws.base(),ws.capacity()},ws.capacity(),dev.stream,outdir);else program.run_hybrid_layer(id,layer,b,mat,gptq,x,y,{ws.base(),ws.capacity()},ws.capacity(),dev.stream);dev.synchronize();std::vector<__nv_bfloat16> out(host.size());output_dev.copy_to_host(out.data(),out.size()*2);std::ofstream of(argv[3],std::ios::binary);of.write(reinterpret_cast<const char*>(out.data()),out.size()*2);of.close();if(!of||std::filesystem::file_size(argv[3])!=out.size()*sizeof(__nv_bfloat16))throw std::runtime_error("output write failed or byte extent mismatch");if(argc>5){program.reset_gptq(gptq,mat);program.release_sequence(id);return 0;}auto committed=program.sequence(id).snapshot();auto committed_kv=program.kv_frontier(id);auto committed_state=program.mamba_state_view(id,layer);std::vector<float> conv_before(3584*3),ssm_before(24*128*256);CUDA_CHECK(cudaMemcpy(conv_before.data(),committed_state.compact_conv,conv_before.size()*sizeof(float),cudaMemcpyDeviceToHost));CUDA_CHECK(cudaMemcpy(ssm_before.data(),committed_state.ssm,ssm_before.size()*sizeof(float),cudaMemcpyDeviceToHost));program.set_failure_injection_for_test(id,6);bool failed=false;try{program.run_hybrid_layer(id,layer,b,mat,gptq,x,y,{ws.base(),ws.capacity()},ws.capacity(),dev.stream);}catch(const std::exception&){failed=true;}dev.synchronize();auto after=program.sequence(id).snapshot();auto after_state=program.mamba_state_view(id,layer);std::vector<float> conv_after(conv_before.size()),ssm_after(ssm_before.size());CUDA_CHECK(cudaMemcpy(conv_after.data(),after_state.compact_conv,conv_after.size()*sizeof(float),cudaMemcpyDeviceToHost));CUDA_CHECK(cudaMemcpy(ssm_after.data(),after_state.ssm,ssm_after.size()*sizeof(float),cudaMemcpyDeviceToHost));if(!failed||after!=committed||program.kv_frontier(id)!=committed_kv||conv_after!=conv_before||ssm_after!=ssm_before)throw std::runtime_error("injected whole-layer failure did not preserve committed KV/Mamba/descriptor generation");std::cout<<"HYBRID_LAYER_OK layer="<<layer<<" tokens="<<T<<" generation="<<after.generation<<" kv_frontier="<<after.kv_frontier<<" rollback=PASS\n";program.reset_gptq(gptq,mat);program.release_sequence(id);return 0;}catch(const std::exception&e){std::cerr<<"STAGE2_FAIL "<<e.what()<<"\n";return 1;}}
